begin
  select id into v_user from auth.users where lower(email) = lower(v_email);
  if v_user is null then
    raise exception 'Compte % introuvable : inscrivez-vous d''abord dans l''app (Connexion cloud → Inscription), puis relancez ce script.', v_email;
  end if;

  -- Comptes créés avant la mise en place des profils : on crée le profil manquant
  insert into public.profiles (id, email, full_name, role)
  values (v_user, v_email, split_part(v_email, '@', 1), 'employee')
  on conflict (id) do nothing;

  -- Pharmacie déjà rattachée au compte (créée à l'inscription ou lors d'un précédent lancement)
  select pm.pharmacy_id into v_ph
  from public.pharmacy_members pm
  where pm.user_id = v_user
  order by (select p.name = v_name from public.pharmacies p where p.id = pm.pharmacy_id) desc
  limit 1;

  if v_ph is not null then
    select count(*) into v_members from public.pharmacy_members where pharmacy_id = v_ph;
    if v_members > 1 then
      raise exception 'La pharmacie liée à % a d''autres membres : ce n''est pas une pharmacie de test, aucune modification faite.', v_email;
    end if;
    update public.pharmacies set name = v_name where id = v_ph;
    update public.pharmacy_members set role = 'admin', employee_name = null
    where user_id = v_user and pharmacy_id = v_ph;
  else
    insert into public.pharmacies (name, invite_code)
    values (v_name, public.generate_invite_code())
    returning id into v_ph;
    insert into public.pharmacy_members (user_id, pharmacy_id, role)
    values (v_user, v_ph, 'admin');
  end if;

  -- Le compte testeur n'est ni support (super-admin) ni propriétaire des suggestions
  update public.app_config
  set value = coalesce((
    select jsonb_agg(e) from jsonb_array_elements_text(value) e where lower(trim(e)) <> lower(v_email)
  ), '[]'::jsonb)
  where key in ('super_admin_emails', 'feedback_owner_emails');

  -- Données de la démo (planning partagé + données personnelles réservées au titulaire)
  insert into public.pharmacy_planning (pharmacy_id, data, updated_by)
  values (v_ph, v_shared, v_user)
  on conflict (pharmacy_id) do update set data = excluded.data, updated_by = excluded.updated_by;

  insert into public.pharmacy_private (pharmacy_id, data, updated_by)
  values (v_ph, v_private, v_user)
  on conflict (pharmacy_id) do update set data = excluded.data, updated_by = excluded.updated_by;

  raise notice 'Pharmacie démo prête pour % (pharmacie %).', v_email, v_ph;
end
$$;

-- Vérification
select p.name as pharmacie, m.role, u.email,
       jsonb_array_length(pl.data->'employees') as salaries,
       jsonb_array_length(pl.data->'conges') as conges,
       jsonb_array_length(pl.data->'reunions') as reunions
from auth.users u
join public.pharmacy_members m on m.user_id = u.id
join public.pharmacies p on p.id = m.pharmacy_id
join public.pharmacy_planning pl on pl.pharmacy_id = p.id
where lower(u.email) = 'p.raveleau@etao.fr';
